const { issues, text } = input;

const list = Array.isArray(issues) ? issues : [];
const q = String(text || '').trim().toLowerCase();

// Optional filter from input.text: a ticket key or a part of the summary
const filtered = q
  ? list.filter(t => {
      const summary = String((t.fields && t.fields.summary) || '').toLowerCase();
      return String(t.key).toLowerCase() === q || summary.includes(q);
    })
  : list;

output = filtered.map(t => ({
  taskId: t.key,
  summary: (t.fields && t.fields.summary) || '',
}));

const toArr = v => Array.isArray(v) ? v : (v ? [v] : []);
const meta = toArr(input.meta);
const results = toArr(input.results);

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const short = v => {
  if (v == null || v === '') {
    return '';
  }
  const s = typeof v === 'string' ? v : JSON.stringify(v, null, 2);
  return s.length > 3000 ? s.slice(0, 3000) + '\n... (truncated)' : s;
};

// Merge Jira meta and tester results by index
const tickets = meta.map((m, i) => {
  const r = results[i] || {};
  const platform = r.platform ? String(r.platform).trim().toLowerCase() : 'unknown';
  return {
    jiraId: m.jiraId || '',
    summary: m.summary || r.summary || '',
    platform,
    route: r.route || '',
    web: r.baas == null ? null : r.baas,
    ios: r.maas == null ? null : r.maas
  };
});

const totals = {
  total: tickets.length,
  web: tickets.filter(t => t.platform === 'web').length,
  ios: tickets.filter(t => t.platform === 'ios').length,
  both: tickets.filter(t => t.platform === 'both').length,
  unknown: tickets.filter(t => !['web', 'ios', 'both'].includes(t.platform)).length
};

const rows = tickets.map(t => {
  const details = [];
  if (t.web != null) {
    details.push('<b>Web</b><pre>' + esc(short(t.web)) + '</pre>');
  }
  if (t.ios != null) {
    details.push('<b>iOS</b><pre>' + esc(short(t.ios)) + '</pre>');
  }
  return (
    '<tr>' +
    '<td>' + esc(t.jiraId) + '</td>' +
    '<td>' + esc(t.summary) + '</td>' +
    '<td>' + esc(t.platform) + '</td>' +
    '<td><details><summary>show</summary>' + details.join('') + '</details></td>' +
    '</tr>'
  );
}).join('');

const html = (
  '<!doctype html><html><head><meta charset="utf-8"><style>' +
  'body{font-family:system-ui,sans-serif;margin:16px;background:#fff;color:#111}' +
  'table{border-collapse:collapse;width:100%}' +
  'th,td{border:1px solid #ddd;padding:6px 8px;text-align:left;vertical-align:top;font-size:13px}' +
  'th{background:#f3f4f6}' +
  'pre{white-space:pre-wrap;word-break:break-word;font-size:11px;background:#f9fafb;padding:6px;max-height:240px;overflow:auto}' +
  '</style></head><body>' +
  '<h3>Test report</h3>' +
  '<p>Tickets: ' + totals.total +
  ' | web: ' + totals.web +
  ' | ios: ' + totals.ios +
  ' | both: ' + totals.both +
  ' | unknown: ' + totals.unknown + '</p>' +
  '<table><tr><th>Jira</th><th>Summary</th><th>Platform</th><th>Result</th></tr>' +
  rows +
  '</table></body></html>'
);

return { html, tickets, totals };

const { d, c } = input;

const { 
  summary = "", 
  description = '(no description provided)'
} = d.fields || {}; 

const commentsArr = c.comments || []; 
const comments = commentsArr.length 
    ? commentsArr.map( c => c.body || '' ).join('\n\n') 
    : '(no comments)'

return { 
  jiraId: d.key, 
  summary, 
  description, 
  comments 
};

const { a, m } = input;
const { error, screenshots } = m;

const analyze = a;

if (error) {
  output = { 
    analyze, 
    error: { error, screenshot: screenshots.screenshot } 
  };
}
else {
  output = { analyze };
}

if (typeof input === 'string') { 
  output = JSON.parse(input) 
} 
else { 
  output = input;
};

if (typeof input === 'string') { 
  const cleanString = input.replace(/\n/g, ''); 
  try {  
    output = JSON.parse(cleanString);
  } 
  catch (e) {  
    output = { 
      error: 'Invalid JSON format', 
      details: e.message 
    };
  }
} 
else if (input && typeof input === 'object') {
  output = input;
} 
else {
  output = { 
    error: 'Unsupported input type',
    details: typeof input
  };
}

output = { 
  response: input.response, 
  toolCalls: input.toolCalls?.map( t => t.result ) 
};

const text = String(input || '');
const match = text.match(/https?:\/\/[^\s'"<>)\]]+/i);

const url = match
              ? match[0].replace(/'/g, '%27')
              : '';

return {
  url,
  found: Boolean(url)
};

