let raw = input.commands;
let commands = [];
let parseError = '';

try {
  if (Array.isArray(raw)) {
    commands = raw;
  }
  else {
    const text = String(raw).trim();

    // Strip code fences and any text around the JSON array
    const start = text.indexOf('[');
    const end = text.lastIndexOf(']');

    if (start === -1 || end === -1 || end < start) {
      throw new Error('No JSON array found in commands: ' + text.slice(0, 200));
    }

    commands = JSON.parse(text.slice(start, end + 1));
  }

  if (!Array.isArray(commands) || commands.length === 0) {
    throw new Error('commands must be a non-empty array');
  }
}
catch (e) {
  parseError = String(e && e.message ? e.message : e);
  commands = [];
}

return {
  body: { commands: commands },
  parseError: parseError
};

const status = Number(input.status) || 0;
const parseError = input.parseError;
const httpError = input.error 
    ? (typeof input.error === 'string' 
        ? input.error 
        : JSON.stringify(input.error)) 
    : null;

const httpOk = status >= 200 && status < 300;
const ok = httpOk && !parseError && !httpError;

return {
  ok: ok,
  status: status,
  response: input.response || null,
  error: parseError || httpError || (httpOk 
      ? null 
      : 'HTTP ' + status)
};

