output = sessions?.find( 
  s => s.device === d && s.status === 'ready' 
)?.id || null;

const { sh } = input;

const s = typeof input.s === 'string' ? JSON.parse(input.s) : input.s;

output = s.testCase.map( (c,i) => ({
  ...c,
  ...( i == 0 ? { snapShot: sh } : [] )
}) );

const results = input.results;

const screenshot = results.find( 
  r => r.action === 'screenshot' 
)?.result || null;

const snapshot = results.find( 
  r => r.action === 'snapshot' 
)?.result || null;

output = { screenshot, snapshot };

const text = typeof input === 'string'
                 ? input
                 : JSON.stringify(input);

